sys_variable_value.value:
(function execute(inputs, outputs) {

    var gr = new GlideRecord('sys_di_task');
    gr.initialize();
    gr.display_name = inputs.name;
    gr.source_table = inputs.source_table_name;
    gr.source_record = inputs.source_record_id;
    gr.is_processed = false;
    gr.agent_input = false;
    gr.task_definition = '54214afa87c32110822cb887cebb35ff';
    gr.status = 'New';
    gr.insert();

    outputs.task_id = gr.sys_id;


})(inputs, outputs);

